update t_product
category_id = #{categoryId}, product_code = #{productCode}, product_name = #{productName}, spec = #{spec}, unit = #{unit}, ref_price = #{refPrice}, supplier_id = #{supplierId}, status = #{status}, remark = #{remark}, image_url = #{imageUrl}, update_by = #{updateBy}, update_time = sysdate()
where enterprise_id = #{enterpriseId} and product_id = #{productId}
